def transform(grid):
    import collections

    H, W = len(grid), len(grid[0])

    # 1. Background color from top and left borders
    border_values = []
    for i in range(H):
        border_values.append(grid[i][0])
    for i in range(W):
        border_values.append(grid[0][i])

    bg_color = collections.Counter(border_values).most_common(1)[0][0]

    # 2. Find connected components for non-background cells
    visited = [[False] * W for _ in range(H)]
    components_by_color = collections.defaultdict(list)

    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg_color and not visited[r][c]:
                color = grid[r][c]
                comp = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                components_by_color[color].append(comp)

    # 3. Find colors with multiple connected components
    multi_comp_colors = [color for color, comps in components_by_color.items() if len(comps) > 1]

    if not multi_comp_colors:
        return grid

    # 4. Select target color: bottom-most component (max row index)
    target_color = None
    max_r = -1
    for color in multi_comp_colors:
        for comp in components_by_color[color]:
            for r, c in comp:
                if r > max_r:
                    max_r = r
                    target_color = color
            if target_color is None:
                break

    if target_color is None:
        return grid

    # 5. Select left-most component of target color
    target_comp = None
    min_c = float('inf')
    for comp in components_by_color[target_color]:
        c_min = min(p[1] for p in comp)
        if c_min < min_c:
            min_c = c_min
            target_comp = comp

    # 6. Extract bounding box
    r_coords = [p[0] for p in target_comp]
    c_coords = [p[1] for p in target_comp]
    r_min, r_max = min(r_coords), max(r_coords)
    c_min, c_max = min(c_coords), max(c_coords)

    # 7. Build transformed output grid
    result = []
    for r in range(r_min, r_max + 1):
        row = []
        for c in range(c_min, c_max + 1):
            val = grid[r][c]
            row.append(target_color if val != bg_color else bg_color)
        result.append(row)

    return result
